#!/usr/bin/env python3# -*- coding: utf-8 -*-"""3. Join@author: oblig0_289412"""from pathlib import Pathimport pandas as pddef get_path(filepath):    path = Path(filepath)    if not path.exists():        raise FileNotFoundError(f"File not found: {filepath}")    return pathdef read_file(filepath):    path = get_path(filepath)    return pd.read_csv(path) abbrevs = pd.read_csv("./data/state-abbrevs.csv")areas = pd.read_csv("./data/state-areas.csv")pop = pd.read_csv("./data/state-population.csv")abbrevs.head(10)print(abbrevs.head(10))def print_lines(areas,pop, abbrevs):    print (areas.columns, pop.columns, abbrevs.columns)    print("\n++++++++++++++++++\n")print_lines(areas,pop, abbrevs)# Jeg forstå ikke helt hvorfor jeg få opp Alaska og ikke Albama som på nettsidendef merge_pop_abbrevs(pop, abbrevs):    merged = pd.merge(        pop, abbrevs, left_on="state/region", right_on="abbreviation", how="outer"    ).drop("abbreviation", axis=1)    return mergeddef check_nulls(df):    result = df.isnull().any()    print(result)    return resultmerged = merge_pop_abbrevs(pop, abbrevs) merged = merged.sort_index()print(merged.head(5))nulls = check_nulls(merged)def show_unmatch_regions(df):   unmatch = df.loc[merged["state"].isnull(), "state/region"].unique()   print(f"({list(unmatch)})")   return (unmatch)   unmatch = show_unmatch_regions(merged)def drop_missing(df):    df.dropna(inplace=True)    return dfmerged = drop_missing(merged)#print (merged) def merge_areas(merged, areas):    final = pd.merge(merged, areas, on="state", how="left")    return final    final = merge_areas(merged, areas)print(final.head())print("\n*******\n")def filter_total_2012(final):    table = final.query("year == 2012 & ages == 'total'")    return tabletable = filter_total_2012(final)print(table.head(10))print("\n--------\n")def compute_density(table):    table.set_index("state", inplace=True)    density = table["population"] / table["area (sq. mi)"]    return density        density = compute_density(table)   print(density.head(5))print("\n:-) :-) :-) :-)(-:\n")def top_density_states(density):    values = density.sort_values(ascending=False).head(10)    return valuesvalues = top_density_states(density)print (values)